const IST = 5.5 * 3600000;
const nowIst = new Date(Date.now() + IST);
const y = nowIst.getUTCFullYear(), m = nowIst.getUTCMonth(), d = nowIst.getUTCDate();
const startMs = Date.UTC(y, m, d, 0, 0, 0) - IST;
const endMs = Date.UTC(y, m, d, 23, 59, 59) - IST;
const label = new Date(startMs + IST).toISOString().slice(0, 10);
return [{ json: { startISO: new Date(startMs).toISOString(), endISO: new Date(endMs).toISOString(), startMs, endMs, dateLabel: label } }];

const win = $('Today\'s window').first().json;
const events = $('Get today\'s calendar events').all().map(i => i.json).filter(e => e && e.id);
const raw = $('Get today\'s Fireflies transcripts').first().json;
const status = raw && raw.statusCode;
const payload = (raw && raw.body) || raw || {};
const ffErrors = payload.errors ? JSON.stringify(payload.errors).slice(0, 400) : '';
const transcripts = (payload.data && payload.data.transcripts) || [];
const norm = s => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const ffTitles = transcripts.map(t => norm(t.title)).filter(Boolean);
const hasLink = e => Boolean(e.hangoutLink || e.conferenceData || /zoom\.us|meet\.google|teams\.microsoft|whereby|webex/i.test([e.location, e.description].filter(Boolean).join(' ')));
// the Google Calendar node's timeMin/timeMax did not bind, so enforce the IST day here
const inWindow = e => { if (!e.start || !e.start.dateTime) return false; const t = new Date(e.start.dateTime).getTime(); return t >= win.startMs && t <= win.endMs; };
const isRealMeeting = e => { if (!e.start || !e.start.dateTime || !e.end || !e.end.dateTime) return false; const mins = (new Date(e.end.dateTime) - new Date(e.start.dateTime)) / 60000; return mins >= 10; };
const considered = events.filter(e => inWindow(e) && isRealMeeting(e) && hasLink(e));
const missed = considered.filter(e => { const t = norm(e.summary); if (!t) return true; return !ffTitles.some(f => f.includes(t) || t.includes(f)); }).map(e => ({ title: e.summary || '(no title)', time: e.start.dateTime, organiser: (e.organizer && e.organizer.email) || '' }));
return [{ json: { dateLabel: win.dateLabel, window: win.startISO + ' -> ' + win.endISO, ff_status: status, ff_errors: ffErrors, calendarEventsReturned: events.length, meetingsToday: considered.length, consideredTitles: considered.map(e => e.summary), transcriptsFound: transcripts.length, transcriptTitles: transcripts.map(t => t.title), missedCount: missed.length, missed } }];
